import {
    Mesh,
    PlaneGeometry,
    MeshBasicNodeMaterial,
    sRGBEncoding,
    Vector3,
    Euler
} from 'three/webgpu';
import gsap from 'gsap';
import { tsl } from 'three/tsl';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} imageUrl
 * @property {[number, number, number]} position
 * @property {[number, number, number]} rotation
 * @property {[number, number, number]} scale
 * @property {Array<{name:string,params:any}>} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {Record<string,Function>} primitives
 * @property {any} fontAtlas
 */

/**
 * Creates a textured plane node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
    const timelines = [];

    // Load texture synchronously via the provided loader
    const texture = ctx.textureLoader(config.imageUrl);
    texture.encoding = sRGBEncoding;
    texture.needsUpdate = true;

    // Determine aspect ratio from the source rect (hard‑coded for this asset)
    const aspect = 512 / 320; // width / height

    // Plane geometry matching the texture aspect
    const geometry = new PlaneGeometry(aspect, 1);

    // Material built with node system (MeshBasicNodeMaterial uses tsl internally)
    const material = new MeshBasicNodeMaterial();
    material.map = texture;
    material.transparent = true;

    // Optional: ensure the material uses a node for color (keeps the node‑based rule)
    material.colorNode = tsl.vec3(1, 1, 1);

    const mesh = new Mesh(geometry, material);

    // Apply scene transforms
    const [px, py, pz] = config.position ?? [0, 0, 0];
    const [rx, ry, rz] = config.rotation ?? [0, 0, 0];
    const [sx, sy, sz] = config.scale ?? [1, 1, 1];

    mesh.position.set(px, py, pz);
    mesh.rotation.set(rx, ry, rz);
    mesh.scale.set(sx, sy, sz);

    // Apply cinematic primitives if any are listed
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives[primitive.name];
            if (typeof fn === 'function') {
                fn(mesh, primitive.params);
            }
        }
    }

    // User data containers for handlers and cleanup
    mesh.userData.handlers = {};

    mesh.userData.cleanup = () => {
        geometry.dispose();
        material.dispose();
        if (texture) texture.dispose();
        timelines.forEach(tl => tl.kill());
    };

    // Example placeholder for future GSAP animations (none defined for this node)
    // const tl = gsap.timeline();
    // timelines.push(tl);

    return mesh;
}
